use gas_data;

-- Generated from A13 monthly flexible query data. Re-runnable for this file_id.
create table if not exists data_monthly_sales_tb (
    id bigint primary key auto_increment,
    stat_date varchar(32) not null,
    region_name varchar(64) not null,
    region_code varchar(64) not null,
    industry_name varchar(64) not null,
    industry_code varchar(64) not null,
    customer_name varchar(128) not null,
    customer_code varchar(64) not null,
    gas_sales varchar(32) not null,
    unit varchar(16) not null,
    file_id varchar(128) not null,
    created_at timestamp not null default current_timestamp,
    key idx_monthly_sales_date (stat_date),
    key idx_monthly_sales_region (region_code),
    key idx_monthly_sales_industry (industry_code),
    key idx_monthly_sales_customer (customer_code)
) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_unicode_ci;

create table if not exists data_daily_sales_tb (
    id bigint primary key auto_increment,
    stat_date varchar(32) not null,
    region_name varchar(64) not null,
    region_code varchar(64) not null,
    industry_name varchar(64) not null,
    industry_code varchar(64) not null,
    customer_name varchar(128) not null,
    customer_code varchar(64) not null,
    gas_sales varchar(32) not null,
    unit varchar(16) not null,
    file_id varchar(128) not null,
    created_at timestamp not null default current_timestamp,
    key idx_daily_sales_date (stat_date),
    key idx_daily_sales_region (region_code),
    key idx_daily_sales_industry (industry_code),
    key idx_daily_sales_customer (customer_code)
) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_unicode_ci;

alter table data_monthly_sales_tb modify id bigint not null auto_increment;
alter table data_daily_sales_tb modify id bigint not null auto_increment;

delete from data_daily_sales_tb where file_id = 'A13-20200101-20201201';
delete from data_monthly_sales_tb where file_id = 'A13-20200101-20201201';






















































































































